import React from 'react';
import {
  Container,
  Typography,
  Paper,
} from '@mui/material';

const Jobs = () => {
  return (
    <Container maxWidth="lg" sx={{ mt: 4, mb: 4 }}>
      <Typography variant="h4" gutterBottom>
        Job Opportunities
      </Typography>
      <Paper elevation={3} sx={{ padding: 4 }}>
        <Typography variant="body1">
          Jobs page - Coming soon...
        </Typography>
        <Typography variant="body2" color="textSecondary" sx={{ mt: 2 }}>
          This page will display job opportunities from partner companies that match your qualifications.
        </Typography>
      </Paper>
    </Container>
  );
};

export default Jobs;
